<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import type { Context, Role, Scenario } from './dashboard';
import { rules, validateFlow, type RuleEdge, type RuleExecution, type RuleFlow, type RuleInput, type RuleIssue, type RuleListQuery, type RuleLogQuery, type RuleNode, type RuleNodeKind, type RuleSample, type RuleSampleCase, type RuleSummary, type RuleVersionDiff } from './rules';
import './dashboard.css';
import './products.css';
import './rules.css';

type View = 'list' | 'editor' | 'logs';
const tenantNames: Record<string, string> = { all: '全部租户', ten_202609_001: '华东智联', ten_202609_002: '全球能源' };
const productNames: Record<string, string> = { prod_as_001: '工业温湿度传感器', prod_as_002: '能源网关' };
const kinds: Record<RuleNodeKind, string> = { trigger: '设备事件', condition: '条件判断', transform: '数据转换', delay: '延迟', alarm: '告警通知', storage: '数据存储', notification: '模拟通知' };
const palette: RuleNodeKind[] = ['trigger', 'condition', 'transform', 'delay', 'alarm', 'storage', 'notification'];
const defaults: Record<RuleNodeKind, RuleNode['config']> = {
  trigger: { field: 'temperature' }, condition: { join: 'AND', clauses: [{ field: 'temperature', operator: '>', threshold: 75 }] }, transform: { field: 'temperature', expression: 'x' },
  delay: { durationMs: 1000 }, alarm: { severity: 'major', message: '设备告警' }, storage: { target: 'iot_atlas' }, notification: { channel: 'email', message: '模拟通知' },
};
const baseList = (): RuleListQuery => ({ tenantId: localStorage.getItem('iot-atlas-current-tenant-v1') || 'all', page: 1, pageSize: 10, seed: 42 });
const baseLog = (): RuleLogQuery => ({ tenantId: localStorage.getItem('iot-atlas-current-tenant-v1') || 'all', page: 1, pageSize: 10, seed: 42 });
const blank = (tenantId: string): RuleInput => ({ tenantId: tenantId === 'all' ? 'ten_202609_001' : tenantId, productId: tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001', name: '', versionNote: '', nodes: [], edges: [] });
const serialize = (value: unknown) => JSON.stringify(value);
const getInput = (flow: RuleFlow): RuleInput => ({ tenantId: flow.tenantId, productId: flow.productId, name: flow.name, versionNote: flow.versionNote, nodes: JSON.parse(JSON.stringify(flow.nodes)) as RuleNode[], edges: JSON.parse(JSON.stringify(flow.edges)) as RuleEdge[] });
const role = ref<Role>('platformAdmin'), scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)');
const systemDark = ref(media.matches);
const updateMedia = () => { systemDark.value = media.matches; };
media.addEventListener('change', updateMedia);
const dark = computed(() => themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value));
watch([dark, themeChoice], () => { document.documentElement.dataset.theme = dark.value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
const canWrite = computed(() => role.value === 'platformAdmin' || role.value === 'tenantAdmin');
const canRun = computed(() => role.value !== 'viewer');
const view = ref<View>('list');
const draftFilters = ref(baseList()), filters = ref(baseList());
const rows = ref<RuleSummary[]>([]), total = ref(0), message = ref(''), reload = ref(0);
const flow = ref<RuleFlow | null>(null), draft = ref<RuleInput>(blank('all'));
const selectedNode = ref<string | null>(null), connectFrom = ref<string | null>(null), issues = ref<RuleIssue[]>([]);
const sampleText = ref(serialize(rules.samples()[0])), execution = ref<RuleExecution | null>(null), confirm = ref<'toggle' | 'apply' | null>(null);
const visibleTraces = ref<number | null>(null);
const caseName = ref(''), savedCases = ref<RuleSampleCase[]>([]), versions = ref<RuleFlow[]>([]);
const fromVersion = ref(1), toVersion = ref(1), versionDiff = ref<RuleVersionDiff | null>(null);
const logDraft = ref(baseLog()), logQuery = ref(baseLog()), logs = ref<RuleExecution[]>([]), logTotal = ref(0), selectedLog = ref<RuleExecution | null>(null);
const canvas = ref<HTMLDivElement | null>(null);
const node = computed(() => draft.value.nodes.find(item => item.id === selectedNode.value));
const dirty = computed(() => flow.value ? serialize(draft.value) !== serialize(getInput(flow.value)) : !!(draft.value.name || draft.value.nodes.length || draft.value.edges.length));
const playback = computed(() => execution.value !== null && visibleTraces.value !== null && visibleTraces.value < execution.value.traces.length);
const traceMap = computed(() => new Map(execution.value?.traces.slice(0, visibleTraces.value ?? execution.value.traces.length).map(item => [item.nodeId, item]) ?? []));
watch([execution, visibleTraces], ([result, count], _old, onCleanup) => { if (!result || count === null) return; if (count >= result.traces.length) { message.value = '试运行完成；设备数据未改变'; return; } const wait = Math.min(1000, Math.max(180, result.traces[count]?.durationMs ?? 180)); const timer = window.setTimeout(() => { if (visibleTraces.value !== null) visibleTraces.value++; }, wait); onCleanup(() => window.clearTimeout(timer)); });
const canvasHeight = computed(() => Math.max(420, ...draft.value.nodes.map(item => item.y + 110)));
const context = (): Context => ({ actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value });
const formatTime = (value: string | null) => value ? new Date(value).toLocaleString('zh-CN') : '暂无';
const toLocal = (value?: string) => value?.slice(0, 16) ?? '';
const fromLocal = (value: string) => value ? new Date(value).toISOString() : undefined;
let listToken = 0, logToken = 0;
async function loadList() { const token = ++listToken; const response = await rules.list(context(), filters.value); if (token !== listToken) return; if ('error' in response) { message.value = response.error.message; rows.value = []; total.value = 0; } else { rows.value = response.data.items; total.value = response.data.total; } }
async function loadLogs() { if (view.value !== 'logs') return; const token = ++logToken; const response = await rules.logsFor(context(), logQuery.value); if (token !== logToken) return; if ('error' in response) { message.value = response.error.message; logs.value = []; logTotal.value = 0; } else { logs.value = response.data.items; logTotal.value = response.data.total; } }
watch([filters, role, scenario, reload], () => void loadList(), { immediate: true });
watch([view, logQuery, role, scenario, reload], () => void loadLogs());
const beforeUnload = (event: BeforeUnloadEvent) => { if (view.value === 'editor' && dirty.value) event.preventDefault(); };
window.addEventListener('beforeunload', beforeUnload);
onBeforeUnmount(() => { media.removeEventListener('change', updateMedia); window.removeEventListener('beforeunload', beforeUnload); });
function changeRole(value: Role) { role.value = value; const tenantId = value === 'platformAdmin' ? 'all' : 'ten_202609_001'; draftFilters.value = { ...baseList(), tenantId }; filters.value = { ...baseList(), tenantId }; logDraft.value = { ...baseLog(), tenantId }; logQuery.value = { ...baseLog(), tenantId }; view.value = 'list'; flow.value = null; execution.value = null; message.value = ''; }
async function loadExtras(id: string) { const [cases, history] = await Promise.all([rules.sampleCases(context(), id), rules.versionHistory(context(), id)]); if ('data' in cases) savedCases.value = cases.data; if ('data' in history) { versions.value = history.data; fromVersion.value = history.data.at(-1)?.version ?? 1; toVersion.value = history.data[0]?.version ?? 1; } versionDiff.value = null; }
async function open(id: string) { const response = await rules.get(context(), id); if ('error' in response) { message.value = response.error.message; return; } flow.value = response.data; draft.value = getInput(response.data); selectedNode.value = response.data.nodes[0]?.id ?? null; issues.value = []; execution.value = null; view.value = 'editor'; message.value = ''; void loadExtras(id); }
function create() { flow.value = null; draft.value = blank(filters.value.tenantId); selectedNode.value = null; issues.value = []; execution.value = null; savedCases.value = []; versions.value = []; versionDiff.value = null; view.value = 'editor'; message.value = ''; }
function updateNode(patch: Partial<RuleNode> & { config?: RuleNode['config'] }) { if (!canWrite.value || !selectedNode.value) return; draft.value = { ...draft.value, nodes: draft.value.nodes.map(item => item.id === selectedNode.value ? { ...item, ...patch, config: patch.config ? { ...item.config, ...patch.config } : item.config } : item) }; execution.value = null; }
function updateClause(index: number, patch: Partial<NonNullable<RuleNode['config']['clauses']>[number]>) { if (!node.value) return; updateNode({ config: { clauses: node.value.config.clauses?.map((item, position) => position === index ? { ...item, ...patch } : item) } }); }
function addNode(kind: RuleNodeKind, x = 40 + (draft.value.nodes.length % 3) * 220, y = 80 + Math.floor(draft.value.nodes.length / 3) * 130) { if (!canWrite.value) return; const id = `${kind}_${Date.now()}_${draft.value.nodes.length}`; draft.value = { ...draft.value, nodes: [...draft.value.nodes, { id, kind, name: kinds[kind], x: Math.min(730, Math.max(0, x)), y: Math.max(0, y), config: structuredClone(defaults[kind]) }] }; selectedNode.value = id; issues.value = []; execution.value = null; }
function drop(event: DragEvent) { event.preventDefault(); if (!canWrite.value || !canvas.value || !event.dataTransfer) return; const bounds = canvas.value.getBoundingClientRect(); const x = event.clientX - bounds.left + canvas.value.scrollLeft - 70, y = event.clientY - bounds.top + canvas.value.scrollTop - 35; const moved = event.dataTransfer.getData('node/id'); if (moved) draft.value = { ...draft.value, nodes: draft.value.nodes.map(item => item.id === moved ? { ...item, x: Math.min(730, Math.max(0, x)), y: Math.max(0, y) } : item) }; else { const kind = event.dataTransfer.getData('node/kind') as RuleNodeKind; if (palette.includes(kind)) addNode(kind, x, y); } }
function connect(to: string) { if (!connectFrom.value || !canWrite.value) return; const edge: RuleEdge = { id: `edge_${Date.now()}`, from: connectFrom.value, to }; const proposed = { ...draft.value, edges: [...draft.value.edges, edge] }; const blocking = validateFlow(proposed).find(issue => issue.code === 'INVALID_EDGE' || issue.code === 'CYCLE'); if (blocking) message.value = blocking.message; else { draft.value = proposed; message.value = '连线已添加'; issues.value = []; } connectFrom.value = null; execution.value = null; }
function validate() { issues.value = validateFlow(draft.value); message.value = issues.value.length ? `发现 ${issues.value.length} 项校验问题` : '规则图校验通过'; }
async function save() { validate(); if (issues.value.length) return; const response = await rules.save(context(), JSON.parse(JSON.stringify(draft.value)) as RuleInput, flow.value?.id, flow.value?.version); if ('error' in response) { message.value = response.error.message; return; } flow.value = response.data; draft.value = getInput(response.data); message.value = '草稿已保存'; reload.value++; void loadExtras(response.data.id); }
async function toggle() { if (!flow.value) return; const response = await rules.toggle(context(), flow.value.id, !flow.value.enabled, flow.value.version); confirm.value = null; if ('error' in response) { message.value = response.error.message; return; } flow.value = response.data; message.value = response.data.enabled ? '规则已启用' : '规则已停用'; reload.value++; void loadExtras(response.data.id); }
function parseSample(): RuleSample | null { try { const parsed = JSON.parse(sampleText.value) as RuleSample; if (!parsed || typeof parsed !== 'object') throw new Error('需要 JSON 对象'); return parsed; } catch (cause) { message.value = `样例 JSON 无效：${(cause as Error).message}`; return null; } }
async function run() { if (!flow.value || dirty.value) { message.value = '请先保存当前规则图'; return; } const sample = parseSample(); if (!sample) return; const response = await rules.testRun(context(), flow.value.id, sample); if ('error' in response) { message.value = response.error.message; return; } execution.value = response.data; visibleTraces.value = 0; message.value = '正在逐节点回放试运行轨迹；设备数据未改变'; }
async function apply() { if (!flow.value) return; const sample = parseSample(); if (!sample) return; const response = await rules.applySimulation(context(), flow.value.id, sample, true); confirm.value = null; if ('error' in response) { message.value = response.error.message; return; } execution.value = response.data; visibleTraces.value = null; message.value = '模拟结果已写入演示日志；设备数据未改变'; reload.value++; }
async function saveCase() { if (!flow.value || !execution.value) return; const sample = parseSample(); if (!sample) return; const response = await rules.saveSampleCase(context(), flow.value.id, caseName.value, sample); if ('error' in response) { message.value = response.error.message; return; } caseName.value = ''; message.value = `测试样例 ${response.data.name} 已保存`; void loadExtras(flow.value.id); }
function selectSavedCase(id: string) { const saved = savedCases.value.find(item => item.id === id); if (saved) { sampleText.value = serialize(saved.sample); execution.value = null; } }
async function compare() { if (!flow.value) return; const response = await rules.compareVersions(context(), flow.value.id, fromVersion.value, toVersion.value); if ('error' in response) { message.value = response.error.message; return; } versionDiff.value = response.data; message.value = `已比较 v${fromVersion.value} 与 v${toVersion.value}`; }
function showLogs() { logDraft.value = { ...logDraft.value, ruleId: flow.value?.id }; logQuery.value = { ...logQuery.value, ruleId: flow.value?.id, page: 1 }; view.value = 'logs'; }
function setSample(index: number) { const sample = rules.samples()[index]; if (sample) { sampleText.value = serialize(sample); execution.value = null; } }
function sampleIndex() { return rules.samples().findIndex(item => serialize(item) === sampleText.value); }
function line(edge: RuleEdge) { const from = draft.value.nodes.find(item => item.id === edge.from), to = draft.value.nodes.find(item => item.id === edge.to); return from && to ? { x1: from.x + 150, y1: from.y + 42, x2: to.x, y2: to.y + 42 } : null; }
</script>

<template>
  <div class="atlas-dashboard atlas-rules"><aside class="atlas-sidebar" aria-label="主导航"><div class="atlas-brand">IoT <strong>Atlas</strong></div><nav><a href="/dashboard">◇ 数据大盘</a><a href="/geography">◇ 全球节点</a><a href="/products">▣ 产品与物模型</a><a href="/devices">▣ 设备中心</a><a class="active" aria-current="page" href="/rules">◇ 规则引擎</a><a href="/firmware">◇ 固件与 OTA</a><a href="/tenants">◇ 租户管理</a><a href="/labs">◇ 实验室</a><a href="/delivery">◇ 交付看板</a></nav><a class="diagnostic-link" href="/">诊断页</a></aside>
  <main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 规则引擎</small><h1>规则引擎</h1><p>编排设备事件，校验并试运行浏览器内的模拟规则。</p></div><div class="header-actions"><label>主题<select aria-label="主题" v-model="themeChoice"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select aria-label="演示身份" :value="role" @change="changeRole(($event.target as HTMLSelectElement).value as Role)"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
  <nav class="rule-page-tabs" aria-label="规则页面"><button :aria-current="view === 'list' ? 'page' : undefined" @click="view = 'list'">规则列表</button><button :aria-current="view === 'editor' ? 'page' : undefined" :disabled="!flow && !draft.nodes.length && !draft.name" @click="view = 'editor'">编排画布</button><button :aria-current="view === 'logs' ? 'page' : undefined" @click="logQuery = { ...logQuery, ruleId: undefined }; view = 'logs'">执行日志</button></nav>
  <div class="dashboard-feedback" aria-live="polite"><span v-if="message" role="status">{{ message }}</span><details class="scenario-control"><summary>Mock 场景</summary><label>服务状态<select aria-label="规则 Mock 场景" v-model="scenario"><option value="normal">正常</option><option value="slow">缓慢</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details></div>
  <template v-if="view === 'list'"><ElCard class="rule-filter"><div class="rule-filter-grid"><label>搜索<input aria-label="搜索规则" v-model="draftFilters.keyword"></label><label>租户<select aria-label="规则租户" v-model="draftFilters.tenantId" :disabled="role !== 'platformAdmin'"><option v-for="(name, id) in tenantNames" :key="id" :value="id">{{ name }}</option></select></label><label>产品<select aria-label="规则产品" :value="draftFilters.productId ?? ''" @change="draftFilters.productId = ($event.target as HTMLSelectElement).value || undefined"><option value="">全部产品</option><option v-for="(name, id) in productNames" :key="id" :value="id">{{ name }}</option></select></label><label>状态<select aria-label="规则状态" :value="draftFilters.enabled === undefined ? '' : String(draftFilters.enabled)" @change="draftFilters.enabled = ($event.target as HTMLSelectElement).value === '' ? undefined : ($event.target as HTMLSelectElement).value === 'true'"><option value="">全部状态</option><option value="true">已启用</option><option value="false">已停用</option></select></label><ElButton type="primary" @click="filters = { ...draftFilters, page: 1 }">查询</ElButton></div></ElCard><ElCard class="rule-list"><div class="product-list-head"><h2>规则列表 <small>共 {{ total }} 条</small></h2><ElButton v-if="canWrite" type="primary" @click="create">新建规则</ElButton></div><div class="product-table-wrap"><table><thead><tr><th>名称</th><th>产品</th><th>状态</th><th>最近执行</th><th>成功率</th><th>版本</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><button @click="open(item.id)">{{ item.name }}</button></td><td>{{ productNames[item.productId] }}</td><td>{{ item.enabled ? '已启用' : '已停用' }}</td><td>{{ formatTime(item.recentExecution) }}</td><td>{{ item.successRate === null ? '暂无' : (item.successRate * 100).toFixed(1) + '%' }}</td><td>v{{ item.version }}</td></tr></tbody></table><p v-if="!rows.length">当前条件没有规则。</p></div><div class="product-pager"><label>每页<select aria-label="规则每页条数" :value="filters.pageSize" @change="filters = { ...filters, page: 1, pageSize: Number(($event.target as HTMLSelectElement).value) }"><option value="2">2</option><option value="10">10</option></select></label><ElButton :disabled="filters.page <= 1" @click="filters = { ...filters, page: filters.page - 1 }">上一页</ElButton><span>{{ filters.page }} / {{ Math.max(1, Math.ceil(total / filters.pageSize)) }}</span><ElButton :disabled="filters.page * filters.pageSize >= total" @click="filters = { ...filters, page: filters.page + 1 }">下一页</ElButton></div></ElCard></template>
  <template v-if="view === 'editor'"><ElCard class="rule-editor-head"><div class="rule-editor-meta"><label>规则名称<input aria-label="规则名称" v-model="draft.name" :disabled="!canWrite"></label><label>租户<select aria-label="编辑规则租户" :value="draft.tenantId" :disabled="!!flow || !canWrite" @change="draft.tenantId = ($event.target as HTMLSelectElement).value; draft.productId = draft.tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001'"><option v-for="(name, id) in tenantNames" v-show="id !== 'all'" :key="id" :value="id">{{ name }}</option></select></label><label>产品<select aria-label="编辑规则产品" v-model="draft.productId" :disabled="!canWrite"><option v-for="(name, id) in productNames" :key="id" :value="id">{{ name }}</option></select></label><label>版本备注<input aria-label="版本备注" v-model="draft.versionNote" :disabled="!canWrite"></label></div><div class="rule-actions"><span>{{ flow ? `v${flow.version} · ${flow.enabled ? '已启用' : '草稿或停用'}` : '未保存规则' }}</span><span v-if="dirty" class="unsaved">● 未保存变更</span><ElButton @click="validate">校验</ElButton><ElButton v-if="canWrite" type="primary" @click="save">保存草稿</ElButton><ElButton v-if="canWrite && flow" @click="confirm = 'toggle'">{{ flow.enabled ? '停用规则' : '启用规则' }}</ElButton><ElButton @click="showLogs">查看日志</ElButton></div></ElCard>
  <div class="rule-editor-grid"><ElCard class="rule-palette"><h2>节点库</h2><p>拖入画布，或点击添加。</p><button v-for="kind in palette" :key="kind" :draggable="canWrite" :disabled="!canWrite" @dragstart="($event as DragEvent).dataTransfer?.setData('node/kind', kind)" @click="addNode(kind)">{{ kinds[kind] }}</button></ElCard>
  <ElCard class="rule-canvas-card"><div class="rule-canvas-head"><h2>编排画布</h2><p>{{ connectFrom ? '选择目标节点的“接入”按钮' : '选中节点，在右侧配置；用“从此连接”和“接入”连线。' }}</p></div><div ref="canvas" class="rule-canvas-scroll" aria-label="规则编排画布" @dragover.prevent @drop="drop"><div class="rule-canvas-inner" :style="{ height: canvasHeight + 'px' }"><svg :viewBox="`0 0 880 ${canvasHeight}`" aria-hidden="true"><defs><marker id="ruleArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#42d8ee" /></marker></defs><template v-for="edge in draft.edges" :key="edge.id"><line v-if="line(edge)" :x1="line(edge)!.x1" :y1="line(edge)!.y1" :x2="line(edge)!.x2" :y2="line(edge)!.y2" stroke="#42d8ee" stroke-width="2" marker-end="url(#ruleArrow)" /></template></svg><div v-for="item in draft.nodes" :key="item.id" class="rule-node" :class="[item.kind, { selected: selectedNode === item.id, invalid: issues.some(issue => issue.nodeId === item.id) }, traceMap.get(item.id)?.status]" :style="{ left: item.x + 'px', top: item.y + 'px' }" :draggable="canWrite" @dragstart="($event as DragEvent).dataTransfer?.setData('node/id', item.id)"><button class="rule-node-main" @click="selectedNode = item.id"><strong>{{ item.name }}</strong><small>{{ kinds[item.kind] }} · {{ traceMap.get(item.id)?.status ?? '待运行' }}</small></button><div class="rule-node-ports"><button :disabled="!canWrite || item.kind === 'trigger'" @click="connect(item.id)">接入</button><button :disabled="!canWrite || ['alarm', 'storage', 'notification'].includes(item.kind)" @click="connectFrom = item.id">从此连接</button></div></div></div></div><div class="rule-edge-list"><h3>连线</h3><span v-for="edge in draft.edges" :key="edge.id">{{ draft.nodes.find(item => item.id === edge.from)?.name }} → {{ draft.nodes.find(item => item.id === edge.to)?.name }} <button v-if="canWrite" :aria-label="`删除连线 ${edge.id}`" @click="draft.edges = draft.edges.filter(item => item.id !== edge.id)">×</button></span></div></ElCard>
  <ElCard class="rule-config"><h2>节点配置</h2><template v-if="node"><p>{{ kinds[node.kind] }} · {{ node.id }}</p><label>节点名称<input aria-label="节点名称" :value="node.name" :disabled="!canWrite" @input="updateNode({ name: ($event.target as HTMLInputElement).value })"></label><label v-if="node.kind === 'trigger'">触发字段<input aria-label="触发字段" :value="node.config.field ?? ''" :disabled="!canWrite" @input="updateNode({ config: { field: ($event.target as HTMLInputElement).value } })"></label><template v-if="node.kind === 'condition'"><label>条件组合<select aria-label="条件组合" :value="node.config.join ?? 'AND'" :disabled="!canWrite" @change="updateNode({ config: { join: ($event.target as HTMLSelectElement).value as 'AND' | 'OR' } })"><option>AND</option><option>OR</option></select></label><div v-for="(clause, index) in node.config.clauses" :key="index" class="rule-clause"><label>字段<input :aria-label="`条件字段 ${index + 1}`" :value="clause.field" :disabled="!canWrite" @input="updateClause(index, { field: ($event.target as HTMLInputElement).value })"></label><label>运算<select :aria-label="`条件运算 ${index + 1}`" :value="clause.operator" :disabled="!canWrite" @change="updateClause(index, { operator: ($event.target as HTMLSelectElement).value as typeof clause.operator })"><option v-for="operator in ['>', '>=', '<', '<=', '==', '!=']" :key="operator">{{ operator }}</option></select></label><label>阈值<input :aria-label="`条件阈值 ${index + 1}`" type="number" :value="clause.threshold" :disabled="!canWrite" @input="updateClause(index, { threshold: Number(($event.target as HTMLInputElement).value) })"></label><button v-if="canWrite" @click="updateNode({ config: { clauses: node.config.clauses?.filter((_, position) => position !== index) } })">删除条件</button></div><ElButton v-if="canWrite" @click="updateNode({ config: { clauses: [...(node.config.clauses ?? []), { field: 'temperature', operator: '>', threshold: 75 }] } })">添加条件</ElButton></template><template v-if="node.kind === 'transform'"><label>转换字段<input aria-label="转换字段" :value="node.config.field ?? ''" :disabled="!canWrite" @input="updateNode({ config: { field: ($event.target as HTMLInputElement).value } })"></label><label>白名单表达式<input aria-label="白名单表达式" :value="node.config.expression ?? ''" :disabled="!canWrite" @input="updateNode({ config: { expression: ($event.target as HTMLInputElement).value } })"></label></template><label v-if="node.kind === 'delay'">延迟毫秒<input aria-label="延迟毫秒" type="number" :value="node.config.durationMs ?? 0" :disabled="!canWrite" @input="updateNode({ config: { durationMs: Number(($event.target as HTMLInputElement).value) } })"></label><template v-if="node.kind === 'alarm'"><label>告警级别<select aria-label="告警级别" :value="node.config.severity ?? 'major'" :disabled="!canWrite" @change="updateNode({ config: { severity: ($event.target as HTMLSelectElement).value as 'critical' | 'major' | 'minor' } })"><option value="critical">严重</option><option value="major">重要</option><option value="minor">次要</option></select></label><label>告警内容<textarea aria-label="告警内容" :value="node.config.message ?? ''" :disabled="!canWrite" @input="updateNode({ config: { message: ($event.target as HTMLTextAreaElement).value } })"></textarea></label></template><label v-if="node.kind === 'storage'">存储目标<input aria-label="存储目标" :value="node.config.target ?? ''" :disabled="!canWrite" @input="updateNode({ config: { target: ($event.target as HTMLInputElement).value } })"></label><template v-if="node.kind === 'notification'"><label>模拟渠道<select aria-label="模拟渠道" :value="node.config.channel ?? 'email'" :disabled="!canWrite" @change="updateNode({ config: { channel: ($event.target as HTMLSelectElement).value as 'email' | 'sms' | 'webhook' } })"><option value="email">邮件</option><option value="sms">短信</option><option value="webhook">Webhook</option></select></label><label>通知内容<textarea aria-label="通知内容" :value="node.config.message ?? ''" :disabled="!canWrite" @input="updateNode({ config: { message: ($event.target as HTMLTextAreaElement).value } })"></textarea></label></template><template v-if="canWrite"><label><input type="checkbox" :checked="!!node.config.simulateTimeout" @change="updateNode({ config: { simulateTimeout: ($event.target as HTMLInputElement).checked } })"> 模拟超时</label><label><input type="checkbox" :checked="!!node.config.simulateFailure" @change="updateNode({ config: { simulateFailure: ($event.target as HTMLInputElement).checked } })"> 模拟失败</label><ElButton @click="draft.nodes = draft.nodes.filter(item => item.id !== node!.id); draft.edges = draft.edges.filter(edge => edge.from !== node!.id && edge.to !== node!.id); selectedNode = null">删除节点</ElButton></template></template><p v-else>选择画布节点后配置。</p></ElCard></div>
  <div class="rule-bottom"><ElCard><h2>校验结果</h2><ul v-if="issues.length" class="rule-issues"><li v-for="(issue, index) in issues" :key="index"><button @click="selectedNode = issue.nodeId">{{ issue.nodeId ?? '整个规则' }}：{{ issue.message }}</button></li></ul><p v-else>点击“校验”检查节点、连线与环路。</p></ElCard><ElCard><div class="product-list-head"><h2>试运行</h2><ElButton type="primary" :disabled="!canRun || !flow || dirty" @click="run">开始试运行</ElButton></div><label>样例报文<select aria-label="样例报文" :value="sampleIndex()" @change="setSample(Number(($event.target as HTMLSelectElement).value))"><option value="-1">自定义 JSON</option><option v-for="(sample, index) in rules.samples()" :key="sample.deviceId" :value="index">{{ sample.deviceId }}</option></select></label><label>报文 JSON<textarea aria-label="报文 JSON" rows="6" :value="sampleText" @input="sampleText = ($event.target as HTMLTextAreaElement).value; execution = null"></textarea></label><label>已保存测试样例<select aria-label="已保存测试样例" @change="selectSavedCase(($event.target as HTMLSelectElement).value)"><option value="">选择已保存样例</option><option v-for="item in savedCases" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><p>试运行只生成轨迹，不修改设备属性或创建告警。</p><template v-if="execution"><p role="status">{{ playback ? '回放中' : `结果：${execution.status}` }} · {{ visibleTraces ?? execution.traces.length }}/{{ execution.traces.length }} 个节点</p><ol class="rule-traces"><li v-for="trace in execution.traces.slice(0, visibleTraces ?? execution.traces.length)" :key="trace.nodeId"><strong>{{ draft.nodes.find(item => item.id === trace.nodeId)?.name ?? trace.nodeId }}</strong> · {{ trace.status }} · {{ trace.durationMs }} ms {{ trace.reason ? '· ' + trace.reason : '' }}<details><summary>输入 / 输出</summary><pre>{{ serialize({ input: trace.input, output: trace.output, matched: trace.matched }) }}</pre></details></li></ol><div v-if="canRun" class="rule-case-actions"><label>样例名称<input v-model="caseName" aria-label="测试样例名称"></label><ElButton :disabled="playback || !caseName.trim()" @click="saveCase">保存为测试样例</ElButton><ElButton :disabled="playback" @click="confirm = 'apply'">应用模拟结果到演示日志</ElButton></div></template></ElCard></div><ElCard v-if="flow" class="rule-version-panel"><h2>版本历史与差异</h2><p>保存草稿或启停时保留版本快照；不会覆盖旧版本。</p><ol><li v-for="item in versions" :key="item.version">v{{ item.version }} · {{ item.versionNote || '无备注' }} · {{ item.enabled ? '已启用' : '已停用' }}</li></ol><div class="rule-version-controls"><label>旧版本<select v-model.number="fromVersion" aria-label="规则旧版本"><option v-for="item in versions" :key="item.version" :value="item.version">v{{ item.version }}</option></select></label><label>新版本<select v-model.number="toVersion" aria-label="规则新版本"><option v-for="item in versions" :key="item.version" :value="item.version">v{{ item.version }}</option></select></label><ElButton :disabled="versions.length < 2" @click="compare">比较版本</ElButton></div><div v-if="versionDiff" role="status" class="rule-version-diff"><p>v{{ versionDiff.from }} → v{{ versionDiff.to }}</p><p>字段：{{ versionDiff.fields.join('、') || '无变化' }}</p><p>新增节点：{{ versionDiff.addedNodes.join('、') || '无' }}；移除节点：{{ versionDiff.removedNodes.join('、') || '无' }}；修改节点：{{ versionDiff.changedNodes.join('、') || '无' }}</p><p>新增连线：{{ versionDiff.addedEdges.join('、') || '无' }}；移除连线：{{ versionDiff.removedEdges.join('、') || '无' }}</p></div></ElCard></template>
  <template v-if="view === 'logs'"><ElCard class="rule-filter"><div class="rule-filter-grid"><label>规则<select aria-label="日志规则" :value="logDraft.ruleId ?? ''" @change="logDraft.ruleId = ($event.target as HTMLSelectElement).value || undefined"><option value="">全部规则</option><option v-for="item in rows" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>设备 ID<input aria-label="日志设备" v-model="logDraft.deviceId"></label><label>状态<select aria-label="日志状态" :value="logDraft.status ?? ''" @change="logDraft.status = (($event.target as HTMLSelectElement).value || undefined) as RuleExecution['status'] | undefined"><option value="">全部</option><option value="succeeded">成功</option><option value="skipped">跳过</option><option value="failed">失败</option></select></label><label>起始时间<input aria-label="日志起始时间" type="datetime-local" :value="toLocal(logDraft.from)" @change="logDraft.from = fromLocal(($event.target as HTMLInputElement).value)"></label><label>结束时间<input aria-label="日志结束时间" type="datetime-local" :value="toLocal(logDraft.to)" @change="logDraft.to = fromLocal(($event.target as HTMLInputElement).value)"></label><ElButton type="primary" @click="logQuery = { ...logDraft, page: 1 }">查询</ElButton></div></ElCard><ElCard class="rule-list"><h2>执行日志 · 共 {{ logTotal }} 条</h2><div class="product-table-wrap"><table><thead><tr><th>时间</th><th>规则</th><th>设备</th><th>状态</th><th>来源</th><th>耗时</th></tr></thead><tbody><tr v-for="item in logs" :key="item.id"><td>{{ formatTime(item.occurredAt) }}</td><td><button @click="selectedLog = item">{{ rows.find(rule => rule.id === item.ruleId)?.name ?? item.ruleId }}</button></td><td><a :href="`/devices?device=${encodeURIComponent(item.deviceId)}`">{{ item.deviceId }}</a></td><td>{{ item.status }}</td><td>{{ item.mode === 'applied' ? '模拟应用' : '事件' }}</td><td>{{ item.traces.reduce((sum, trace) => sum + trace.durationMs, 0) }} ms</td></tr></tbody></table><p v-if="!logs.length">当前筛选没有执行日志。试运行不会自动写入日志。</p></div><div class="product-pager"><ElButton :disabled="logQuery.page <= 1" @click="logQuery = { ...logQuery, page: logQuery.page - 1 }">上一页</ElButton><span>{{ logQuery.page }} / {{ Math.max(1, Math.ceil(logTotal / logQuery.pageSize)) }}</span><ElButton :disabled="logQuery.page * logQuery.pageSize >= logTotal" @click="logQuery = { ...logQuery, page: logQuery.page + 1 }">下一页</ElButton></div></ElCard><ElCard v-if="selectedLog" class="rule-log-detail"><div class="product-list-head"><h2>节点执行轨迹 · {{ selectedLog.id }}</h2><ElButton @click="selectedLog = null">关闭</ElButton></div><details v-for="trace in selectedLog.traces" :key="trace.nodeId"><summary>{{ trace.nodeId }} · {{ trace.status }} · {{ trace.durationMs }} ms {{ trace.reason ? '· ' + trace.reason : '' }}</summary><pre>{{ serialize({ input: trace.input, output: trace.output, matched: trace.matched }) }}</pre></details></ElCard></template>
  </main><div v-if="confirm" class="product-modal-backdrop"><div class="product-modal" role="dialog" aria-modal="true" :aria-label="confirm === 'toggle' ? '启停规则确认' : '应用模拟结果确认'"><h2>{{ confirm === 'toggle' ? flow?.enabled ? '停用规则' : '启用规则' : '应用模拟结果' }}</h2><p>{{ confirm === 'toggle' ? `影响所选产品的 6 台演示设备；当前版本 v${flow?.version}。启用后只消费模拟事件。` : '将当前试运行结果写入演示日志并生成模拟告警记录，设备属性保持不变。' }}</p><div><ElButton type="primary" @click="confirm === 'toggle' ? toggle() : apply()">确认</ElButton><ElButton @click="confirm = null">取消</ElButton></div></div></div></div>
</template>
